with base as (select id, product_id, quantity, unit_price, round(unit_price * 1.07, 2) as unit_price_adjusted, least(quantity, unit_price) as least_quantity_unit_price from order_items where order_id = 38) select id, quantity, unit_price, lag(unit_price) over (partition by product_id order by least_quantity_unit_price, id) as prev_unit_price, lead(unit_price) over (partition by product_id order by least_quantity_unit_price, id) as next_unit_price, lead(least_quantity_unit_price) over (partition by product_id order by least_quantity_unit_price, id) as next_least_quantity_unit_price, lag(least_quantity_unit_price) over (partition by product_id order by least_quantity_unit_price, id) as prev_least_quantity_unit_price, row_number() over (partition by product_id order by least_quantity_unit_price, id) as seq_no, avg(quantity) over (partition by product_id order by unit_price_adjusted, id rows between 3 preceding and current row) as quantity_avg_3 from base where unit_price < 330
